// Source-integrity classification of every Audit & Assurance chapter, and the practice items it lets through.
// Classified on 2026-11-08 by comparing each chapter's title, objective, displayed text (as generated by
// auditAssuranceCore.tsx), key terms, visual and the cards/activities mapped to it. This supersedes the
// `alignment` flags in source.ts for eligibility. Full evidence and the content-owner remediation list are in
// reports/audit-assurance-source-integrity-2026-11-08.md.
//
// A Fully Aligned: eligible. B Partially Aligned: only directly supported concepts are eligible (each kept
// card was checked against them). C Misaligned and D Restricted/Unverifiable: never eligible.
// Eligibility fails closed: a card or activity is offered only if it is listed in VALIDATED_* below AND every
// chapter it maps to or cites is A or B. New content stays ineligible until it is reviewed and listed.

export type ChapterIntegrityClass = 'A' | 'B' | 'C' | 'D';

export interface ChapterIntegrity {
  moduleKey: string;
  lessonTitle: string;
  /** 1-based lesson-local chapter number. */
  chapterNumber: number;
  /** Title without the numeric prefix, as in source.ts. */
  title: string;
  integrity: ChapterIntegrityClass;
  /** Why, in one sentence (empty for A). */
  note: string;
}

type Row = [chapterNumber: number, title: string, integrity: ChapterIntegrityClass, note: string];

const module = (moduleKey: string, lessons: Array<[lessonTitle: string, rows: Row[]]>): ChapterIntegrity[] =>
  lessons.flatMap(([lessonTitle, rows]) => rows.map(([chapterNumber, title, integrity, note]) => ({ moduleKey, lessonTitle, chapterNumber, title, integrity, note })));

