const integrityOf = new Map(PROFESSIONAL_AUDIT_CHAPTER_INTEGRITY.map((row) => [`${row.moduleKey}::${row.lessonTitle}::${row.chapterNumber}`, row.integrity]));

/** The class of a chapter, or null when it is not classified (treated as ineligible). */
export function chapterIntegrity(moduleKey: string, lessonTitle: string, chapterNumber: number): ChapterIntegrityClass | null {
  return integrityOf.get(`${moduleKey}::${lessonTitle}::${chapterNumber}`) ?? null;
}

export const isEligibleChapter = (moduleKey: string, lessonTitle: string, chapterNumber: number) => {
  const integrity = chapterIntegrity(moduleKey, lessonTitle, chapterNumber);
  return integrity === 'A' || integrity === 'B';
};
